// Model-based conformance: replay traces generated by `quint run --mbt`
// against the implementation and compare state after every step.
//
//   quint run orders.qnt --mbt --n-traces 200 --max-steps 15 --out-itf "traces/t{seq}.itf.json"
//   node --test conformance.test.ts
//   BUGGY_IMPL=1 node --test conformance.test.ts   # implementation with the planted bug

import { test } from "node:test";
import assert from "node:assert/strict";
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { OrderSystem, type Actor } from "../impl/orders.ts";

const TRACE_DIR = join(import.meta.dirname, "traces");
const buggyImpl = process.env.BUGGY_IMPL === "1";

// ---- decode Quint's ITF JSON into plain values ----
type Itf = any;
const int = (v: Itf): number => Number(v["#bigint"]);
const tag = (v: Itf): string => v.tag;
const pick = (v: Itf): Itf => v.value; // Some(x) -> x

function specState(s: Itf) {
  return {
    orders: Object.fromEntries(s.orders["#map"].map(([k, v]: Itf[]) => [int(k), tag(v)])),
    invoices: Object.fromEntries(
      s.invoices["#map"].map(([k, v]: Itf[]) => [int(k), { order: int(v.order), status: tag(v.status) }]),
    ),
    outbox: s.outbox["#set"].map((n: Itf) => `${tag(n.kind)}:${int(n.invoice)}`).sort(),
  };
}

function implState(sys: OrderSystem) {
  return {
    orders: Object.fromEntries(sys.orders),
    invoices: Object.fromEntries([...sys.invoices].map(([k, v]) => [k, { ...v }])),
    outbox: [...new Set(sys.outbox.map((n) => `${n.kind}:${n.invoice}`))].sort(),
  };
}

function apply(sys: OrderSystem, s: Itf): void {
  const picks = s["mbt::nondetPicks"];
  const actor = tag(pick(picks.actor)) as Actor;
  const o = int(pick(picks.o));
  const i = int(pick(picks.i));
  switch (s["mbt::actionTaken"]) {
    case "createOrder": return sys.createOrder(actor, o);
    case "confirmOrder": return sys.confirmOrder(actor, o);
    case "issueInvoice": return sys.issueInvoice(actor, o, i);
    case "voidInvoice": return sys.voidInvoice(actor, i);
    case "payInvoice": return sys.payInvoice(actor, i);
    case "fulfilOrder": return sys.fulfilOrder(actor, o);
    case "cancelOrder": return sys.cancelOrder(actor, o);
    default: throw new Error(`unknown action ${s["mbt::actionTaken"]}`);
  }
}

const files = readdirSync(TRACE_DIR).filter((f) => f.endsWith(".itf.json")).sort();

test(`implementation follows ${files.length} spec traces`, () => {
  assert.ok(files.length > 0, "no traces: run quint with --mbt first");
  let steps = 0;
  for (const file of files) {
    const trace = JSON.parse(readFileSync(join(TRACE_DIR, file), "utf8"));
    const sys = new OrderSystem({ cancelVoidsInvoice: !buggyImpl });
    for (const state of trace.states.slice(1)) {
      const where = `${file} step ${state["#meta"].index} (${state["mbt::actionTaken"]})`;
      // The spec took this step, so the implementation must accept it...
      assert.doesNotThrow(() => apply(sys, state), `impl rejected a step the spec allows: ${where}`);
      // ...and must end up in the same state.
      assert.deepEqual(implState(sys), specState(state), `state diverged at ${where}`);
      steps++;
    }
  }
  console.log(`replayed ${steps} steps from ${files.length} traces`);
});
